using Framework.Parameters;
using UnityEngine;

namespace Game.AI.Parameters
{
    /// <summary>
    /// 迷路内の敵の初期能力と性格を定義する。
    /// </summary>
    /// <remarks>
    /// 実行時の状態は保持しない。
    /// 複数のエージェントで同一アセットを共有できる。
    /// </remarks>
    [CreateAssetMenu(
        fileName = "MazeEnemyProfile",
        menuName = "Game/AI/Maze Enemy Profile",
        order = 100)]
    public sealed class MazeEnemyProfile : ScriptableObject
    {
        [Header("基本情報")]

        [SerializeField]
        [Tooltip("敵プロファイルの表示名。")]
        private string displayName = "標準型";

        [SerializeField]
        [TextArea(2, 5)]
        [Tooltip("敵の性格や特徴に関する説明。")]
        private string description = "";

        [Header("基本能力")]

        [SerializeField]
        [Range(0f, 12f)]
        [Tooltip("基本移動速度。セル毎秒。")]
        private float moveSpeed = 3.5f;

        [SerializeField]
        [Range(0f, 3f)]
        [Tooltip("追跡時の移動速度倍率。")]
        private float chaseSpeedMultiplier = 1.15f;

        [SerializeField]
        [Range(0f, 3f)]
        [Tooltip("逃走時の移動速度倍率。")]
        private float escapeSpeedMultiplier = 1.3f;

        [Header("認識能力")]

        [SerializeField]
        [Range(0f, 64f)]
        [Tooltip("プレイヤーを認識する距離。セル単位。")]
        private float detectionRange = 6f;

        [SerializeField]
        [Range(0f, 64f)]
        [Tooltip("脅威を認識する距離。セル単位。")]
        private float threatDetectionRange = 8f;

        [SerializeField]
        [Range(0f, 60f)]
        [Tooltip("認識対象を記憶する時間。秒単位。")]
        private float memoryDuration = 5f;

        [Header("聴覚能力")]

        /// <summary>
        /// 仮想音源を認識する基準聴覚範囲。
        /// </summary>
        [SerializeField]
        [Range(0f, 64f)]
        [Tooltip("基準聴覚範囲。セル単位。0の場合は聴覚を無効化する。")]
        private float hearingRange = 8f;

        /// <summary>
        /// 仮想音源に対する聴覚感度。
        /// </summary>
        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("音に対する感度。高いほど遠くの音を認識できる。")]
        private float hearingSensitivity = 0.5f;

        /// <summary>
        /// 音源の位置を推定する精度。
        /// </summary>
        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("音源位置の推定精度。高いほど正確に位置を特定できる。")]
        private float hearingAccuracy = 0.5f;

        [Header("性格")]

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("プレイヤーを積極的に追跡する傾向。")]
        private float aggression = 0.5f;

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("危険を回避しようとする傾向。")]
        private float caution = 0.5f;

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("対象を追い続けようとする傾向。")]
        private float persistence = 0.5f;

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("回り込みや移動予測を重視する傾向。")]
        private float tacticalIntelligence = 0.3f;

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("自分の縄張りを重視する傾向。")]
        private float territoriality = 0.3f;

        [Header("行動傾向")]

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("未探索領域を優先する傾向。")]
        private float exploration = 0.5f;

        [SerializeField]
        [Range(0f, 1f)]
        [Tooltip("通常巡回を選択する傾向。")]
        private float patrolPreference = 0.5f;

        [SerializeField]
        [Range(0f, 64f)]
        [Tooltip("縄張りの基準範囲。セル単位。")]
        private float territoryRadius = 5f;

        [SerializeField]
        [Range(0f, 300f)]
        [Tooltip("訪問したセルを記憶する時間。秒単位。")]
        private float visitMemoryDuration = 30f;

        [SerializeField]
        [Range(0f, 5f)]
        [Tooltip("対象の移動を予測する時間。秒単位。")]
        private float predictionTime = 1f;

        /// <summary>
        /// プロファイルの表示名。
        /// </summary>
        public string DisplayName => displayName;

        /// <summary>
        /// プロファイルの説明。
        /// </summary>
        public string Description => description;

        /// <summary>
        /// 指定されたパラメーターの初期値を取得する。
        /// </summary>
        /// <param name="id">パラメーター識別子</param>
        /// <returns>定義範囲内に補正された初期値</returns>
        public float GetInitialValue(MazeEnemyParameter id)
        {
            var definition =
                MazeEnemyParameterCatalog.GetDefinition(id);

            float value;

            switch (id)
            {
                case MazeEnemyParameter.MoveSpeed:
                    value = moveSpeed;
                    break;

                case MazeEnemyParameter.ChaseSpeedMultiplier:
                    value = chaseSpeedMultiplier;
                    break;

                case MazeEnemyParameter.EscapeSpeedMultiplier:
                    value = escapeSpeedMultiplier;
                    break;

                case MazeEnemyParameter.DetectionRange:
                    value = detectionRange;
                    break;

                case MazeEnemyParameter.ThreatDetectionRange:
                    value = threatDetectionRange;
                    break;

                case MazeEnemyParameter.MemoryDuration:
                    value = memoryDuration;
                    break;
                
                case MazeEnemyParameter.HearingRange:
                    value = hearingRange;
                    break;

                case MazeEnemyParameter.HearingSensitivity:
                    value = hearingSensitivity;
                    break;

                case MazeEnemyParameter.HearingAccuracy:
                    value = hearingAccuracy;
                    break;

                case MazeEnemyParameter.Aggression:
                    value = aggression;
                    break;

                case MazeEnemyParameter.Caution:
                    value = caution;
                    break;

                case MazeEnemyParameter.Persistence:
                    value = persistence;
                    break;

                case MazeEnemyParameter.TacticalIntelligence:
                    value = tacticalIntelligence;
                    break;

                case MazeEnemyParameter.Territoriality:
                    value = territoriality;
                    break;

                case MazeEnemyParameter.Exploration:
                    value = exploration;
                    break;

                case MazeEnemyParameter.PatrolPreference:
                    value = patrolPreference;
                    break;

                case MazeEnemyParameter.TerritoryRadius:
                    value = territoryRadius;
                    break;

                case MazeEnemyParameter.VisitMemoryDuration:
                    value = visitMemoryDuration;
                    break;

                case MazeEnemyParameter.PredictionTime:
                    value = predictionTime;
                    break;

                default:
                    value = definition.DefaultValue;
                    break;
            }

            // 不正な数値は共通定義の初期値へ戻す。
            if (float.IsNaN(value) ||
                float.IsInfinity(value))
            {
                return definition.DefaultValue;
            }

            return definition.Clamp(value);
        }

        /// <summary>
        /// このプロファイルを使用した
        /// 独立した実行時パラメーターセットを生成する。
        /// </summary>
        /// <returns>生成した実行時パラメーターセット</returns>
        public ParameterSet<MazeEnemyParameter>
            CreateParameterSet()
        {
            var parameterSet =
                new ParameterSet<MazeEnemyParameter>();

            try
            {
                // プロファイルの値を実行時の初期値として登録する。
                foreach (var definition in
                    MazeEnemyParameterCatalog.Definitions)
                {
                    parameterSet.TryRegister(
                        definition,
                        GetInitialValue(definition.Id));
                }

                return parameterSet;
            }
            catch
            {
                // 生成途中で失敗した場合は登録内容を解放する。
                parameterSet.Dispose();

                throw;
            }
        }
    }
}
